parameters.jsCode:
const item = $input.first().json;
const parts = [];

if (item.imageBase64 && item.mimeType) {
  parts.push({
    inlineData: {
      mimeType: item.mimeType,
      data: item.imageBase64
    }
  });
}

let promptText = 'USER MESSAGE: ' + (item.message || '(Image uploaded without text)') + '\n\n';
promptText += 'OPERATION HINT: ' + item.actionHint + '\n';
promptText += 'LOCALE: ' + item.locale + '\n\n';

// 1. Inventory Context
if (item.inventoryContext && item.inventoryContext.length > 0) {
  promptText += 'CURRENT FRIDGE INVENTORY CONTEXT (Authoritative database records):\n';
  for (const inv of item.inventoryContext) {
    promptText += '- ID: ' + (inv.id || 'N/A') + ' | ' + (inv.name || 'Unknown') + ' | Quantity: ' + (inv.quantity ?? 'N/A') + ' ' + (inv.unit || '') + ' | Category: ' + (inv.category || 'Others') + (inv.expiryDate ? ' | Expiry: ' + inv.expiryDate : '') + '\n';
  }
  promptText += '\n';
} else {
  promptText += 'CURRENT FRIDGE INVENTORY CONTEXT: (Empty fridge — No items currently in inventory)\n\n';
}

// 2. User Preferences & Nutrition Goals
if (item.userPreferences && Object.keys(item.userPreferences).length > 0) {
  promptText += 'USER PREFERENCES & GOALS:\n' + JSON.stringify(item.userPreferences) + '\n\n';
}

// 3. Today's Nutrition Progress
if (item.todayNutrition && Object.keys(item.todayNutrition).length > 0) {
  promptText += 'TODAY NUTRITION INTAKE (Calories & Macros):\n' + JSON.stringify(item.todayNutrition) + '\n\n';
}

// 4. Recent Meals History
if (item.recentMeals && item.recentMeals.length > 0) {
  promptText += 'RECENT MEAL HISTORY TODAY:\n';
  for (const m of item.recentMeals.slice(-3)) {
    promptText += '- ' + (m.mealType || 'Meal') + ': ' + m.name + ' (' + (m.calories ?? 0) + ' kcal, P:' + (m.proteinG ?? 0) + 'g, C:' + (m.carbsG ?? 0) + 'g, F:' + (m.fatG ?? 0) + 'g)\n';
  }
  promptText += '\n';
}

// 5. Recent Conversation Messages
if (item.conversationHistory && item.conversationHistory.length > 0) {
  promptText += 'RECENT CONVERSATION HISTORY:\n';
  for (const c of item.conversationHistory.slice(-5)) {
    promptText += '- [' + (c.role || 'user') + ']: ' + (c.text || c.message || '') + '\n';
  }
  promptText += '\n';
}

promptText += 'Analyze the request carefully according to your system instructions and respond strictly in valid JSON.';

parts.push({ text: promptText });

const systemInstructionText = `You are the NutriFridge AI Food & Nutrition Assistant for the NutriFridge mobile application.
Your role is to assist users with fridge inventory management, recipe and meal recommendations, food queries, and meal tracking.

CRITICAL CONSTRAINTS & BEHAVIORAL RULES:
1. INVENTORY ACCURACY (NEVER INVENT INVENTORY):
   - When answering questions about stock or recommending recipes, use ONLY the items present in "CURRENT FRIDGE INVENTORY CONTEXT".
   - If an ingredient is NOT in the inventory context, treat it as MISSING (put in "missingIngredients"). Never claim the user has an ingredient that is not listed.
   - If the inventory context is empty or missing, explicitly inform the user that their fridge is currently empty and suggest adding ingredients.

2. MEAL RECOMMENDATIONS (action: "meal_recommendation"):
   - Recommend meals using the available inventory as the primary source.
   - Distinguish available ingredients from missing ones (put missing ones in "missingIngredients").
   - For each ingredient in "ingredients", if it matches an item in the fridge inventory, provide its exact "matchedInventoryItemId" from the inventory context. Set "matchedInventoryItemId: null" for items not in the fridge.
   - Tailor recommendations to user dietary preferences (vegetarian, vegan, allergies, etc.) and calorie/protein targets.
   - If the inventory is too depleted to prepare any recommended meal, return action: "no_match" with an encouraging assistantMessage suggesting a few staple ingredients to buy.

3. NUTRITION & CALORIE ESTIMATES:
   - Nutrition numbers (calories, protein, carbs, fat) are approximate AI estimates (nutritionIsEstimate: true).
   - Never provide medical or clinical nutritional advice. Add an estimate note.

4. MEAL LOGGING & DEDUCTIONS:
   - All ingredient deductions require explicit user confirmation (deductionNeedsUserConfirmation: true).
   - Gemini does NOT mutate the database directly. Output action "meal_recommendation" or "log_meal" with structured data for the user to review and confirm.

5. EXACT 11 CANONICAL CATEGORIES FOR ANY PROPOSED INVENTORY ITEMS:
   Every item in "inventoryItems" MUST use exactly one of these 11 categories:
   - "Dairy Products"
   - "Vegetables"
   - "Fruits"
   - "Non-Veg"
   - "Meals & Leftovers"
   - "Packaged Food"
   - "Drinks & Juices"
   - "Ice Cream"
   - "Frozen Food"
   - "Dry Fruits"
   - "Others"

OUTPUT SCHEMA (STRICT JSON ONLY):
{
  "action": "meal_recommendation" | "log_meal" | "add_inventory_items" | "remove_inventory_items" | "query_inventory" | "assistant_reply" | "clarification_needed" | "no_match",
  "assistantMessage": "Helpful and friendly response text formatted with clear Markdown where appropriate",
  "requiresConfirmation": boolean,
  "needsClarification": boolean,
  "clarifyingQuestion": string | null,
  "inventoryItems": [
    {
      "name": "string",
      "category": "Dairy Products" | "Vegetables" | "Fruits" | "Non-Veg" | "Meals & Leftovers" | "Packaged Food" | "Drinks & Juices" | "Ice Cream" | "Frozen Food" | "Dry Fruits" | "Others",
      "quantity": number | null,
      "unit": "g" | "kg" | "ml" | "L" | "pieces" | "pack" | "bottle" | null,
      "expiryDate": "YYYY-MM-DD" | null,
      "expiryDaysEstimate": number | null,
      "confidence": number
    }
  ],
  "meal": {
    "name": "string",
    "mealType": "breakfast" | "lunch" | "dinner" | "snack",
    "description": "string",
    "preparationTimeMinutes": number,
    "reason": "string (why this meal suits their fridge & goals)",
    "ingredients": [
      {
        "name": "string",
        "quantity": number | null,
        "unit": "g" | "ml" | "pieces" | null,
        "matchedInventoryItemId": "string (UUID)" | null,
        "suggestedDeductionQuantity": number | null,
        "deductionNeedsUserConfirmation": true
      }
    ],
    "missingIngredients": ["string"],
    "calories": number,
    "proteinG": number,
    "carbsG": number,
    "fatG": number,
    "nutrition": {
      "calories": number,
      "proteinG": number,
      "carbsG": number,
      "fatG": number,
      "isEstimate": true,
      "estimateNote": "Approximate nutrition estimate"
    }
  } | null,
  "warnings": ["string"]
}`;

const geminiPayload = {
  contents: [
    {
      role: 'user',
      parts: parts
    }
  ],
  systemInstruction: {
    parts: [
      { text: systemInstructionText }
    ]
  },
  generationConfig: {
    maxOutputTokens: 2048,
    responseMimeType: 'application/json',
    thinkingConfig: {
      thinkingLevel: 'low'
    }
  }
};

const targetModel = item.targetModel || 'gemini-3.8-flash';
const apiUrl = 'https://generativelanguage.googleapis.com/v1beta/models/' + targetModel + ':generateContent';

return [{
  json: {
    requestId: item.requestId,
    apiUrl: apiUrl,
    geminiPayload: geminiPayload,
    promptBuildTimestamp: Date.now()
  }
}];

const inputItem = $input.first().json;
const originalRequestId = $('Validate Request & Auth Secret').first().json.requestId || 'req_unknown';
const promptBuildTimestamp = $('Prepare Context & Gemini Prompt').first().json.promptBuildTimestamp || Date.now();
const geminiDurationMs = Date.now() - promptBuildTimestamp;

// Handle upstream network or API errors
if (inputItem.error || inputItem.statusCode >= 400) {
  const errObj = inputItem.error || {};
  const errMsg = String(errObj.message || errObj.description || '').toLowerCase();
  const errCode = String(errObj.code || '').toUpperCase();
  const isTimeout = errCode === 'ECONNABORTED' || errCode === 'ETIMEDOUT' || errMsg.includes('timeout') || errMsg.includes('timed out');
  const status = inputItem.statusCode || (isTimeout ? 504 : (inputItem.error ? 502 : 500));
  let errorCode = 'GEMINI_UPSTREAM_ERROR';
  let userMessage = 'NutriFridge could not complete AI analysis at this time. Please tap retry.';
  let retryable = true;
  if (isTimeout || status === 504) {
    errorCode = 'GEMINI_REQUEST_TIMEOUT';
    userMessage = 'Google Gemini request timed out while generating your meal plan. Please tap retry.';
    retryable = true;
  } else if (status === 429) {
    errorCode = 'GEMINI_RATE_LIMIT_EXCEEDED';
    userMessage = 'Google Gemini rate limit exceeded. Please wait a moment and tap retry.';
    retryable = true;
  } else if (status === 401 || status === 403) {
    errorCode = 'GEMINI_AUTH_FAILED';
    userMessage = 'Google Gemini authentication failed. Please verify the Gemini Header Auth credential in n8n.';
    retryable = false;
  } else if (status === 400) {
    errorCode = 'GEMINI_INVALID_REQUEST';
    userMessage = 'Google Gemini rejected the request format. Please shorten or simplify your input.';
    retryable = false;
  }
  return [{
    json: {
      ok: false,
      httpStatus: status === 401 || status === 403 ? 502 : (status === 504 ? 504 : status),
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        action: 'error',
        assistantMessage: userMessage,
        error: {
          code: errorCode,
          message: userMessage,
          retryable: retryable
        },
        timings: {
          geminiDurationMs: geminiDurationMs
        }
      }
    }
  }];
}

// Extract text from Gemini candidates
const candidates = inputItem.candidates;
if (!candidates || !Array.isArray(candidates) || candidates.length === 0) {
  return [{
    json: {
      ok: false,
      httpStatus: 502,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        action: 'error',
        assistantMessage: 'AI returned an empty response candidate. Please tap retry.',
        error: { code: 'EMPTY_CANDIDATE', message: 'No candidate in Gemini response' },
        timings: { geminiDurationMs: geminiDurationMs }
      }
    }
  }];
}

let combinedText = '';
for (const part of candidates[0].content?.parts || []) {
  if (part.text) combinedText += part.text;
}

combinedText = combinedText.trim();
if (combinedText.startsWith('```')) {
  combinedText = combinedText.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(combinedText);
} catch (e) {
  return [{
    json: {
      ok: false,
      httpStatus: 502,
      responseBody: {
        ok: false,
        requestId: originalRequestId,
        action: 'error',
        assistantMessage: 'AI output could not be parsed as valid JSON. Please tap retry.',
        error: { code: 'INVALID_AI_JSON', message: e.message },
        timings: { geminiDurationMs: geminiDurationMs }
      }
    }
  }];
}

const CANONICAL_CATEGORIES = [
  'Dairy Products',
  'Vegetables',
  'Fruits',
  'Non-Veg',
  'Meals & Leftovers',
  'Packaged Food',
  'Drinks & Juices',
  'Ice Cream',
  'Frozen Food',
  'Dry Fruits',
  'Others'
];

function normalizeCategory(cat) {
  if (!cat || typeof cat !== 'string') return 'Others';
  const clean = cat.trim();
  for (const c of CANONICAL_CATEGORIES) {
    if (c.toLowerCase() === clean.toLowerCase()) return c;
  }
  const u = clean.toUpperCase();
  if (u.includes('DAIRY')) return 'Dairy Products';
  if (u.includes('ICE CREAM')) return 'Ice Cream';
  if (u.includes('FROZEN')) return 'Frozen Food';
  if (u.includes('DRY FRUIT')) return 'Dry Fruits';
  if (u.includes('NON-VEG') || u.includes('NON VEG')) return 'Non-Veg';
  if (u.includes('LEFTOVER') || u.includes('MEAL')) return 'Meals & Leftovers';
  if (u.includes('PACKAGE')) return 'Packaged Food';
  if (u.includes('DRINK') || u.includes('JUICE')) return 'Drinks & Juices';
  if (u.includes('VEG')) return 'Vegetables';
  if (u.includes('FRUIT')) return 'Fruits';
  return 'Others';
}

const action = parsed.action || 'assistant_reply';
const assistantMessage = parsed.assistantMessage || 'Processed your request successfully.';
const requiresConfirmation = Boolean(parsed.requiresConfirmation);
const needsClarification = Boolean(parsed.needsClarification);
const clarifyingQuestion = parsed.clarifyingQuestion || null;

let inventoryItems = [];
if (Array.isArray(parsed.inventoryItems)) {
  for (const it of parsed.inventoryItems) {
    if (it && typeof it === 'object' && it.name) {
      inventoryItems.push({
        name: String(it.name).trim(),
        category: normalizeCategory(it.category),
        quantity: typeof it.quantity === 'number' && it.quantity > 0 ? it.quantity : null,
        unit: it.unit ? String(it.unit).trim() : 'pieces',
        expiryDate: it.expiryDate || null,
        expiryDaysEstimate: typeof it.expiryDaysEstimate === 'number' ? it.expiryDaysEstimate : null,
        confidence: typeof it.confidence === 'number' ? Math.min(1.0, Math.max(0.0, it.confidence)) : 0.95
      });
    }
  }
}

let meal = null;
if ((action === 'meal_recommendation' || action === 'log_meal') && parsed.meal && typeof parsed.meal === 'object') {
  const m = parsed.meal;
  const ingredients = [];
  for (const ing of m.ingredients || []) {
    if (ing && typeof ing === 'object' && ing.name) {
      ingredients.push({
        name: String(ing.name).trim(),
        quantity: typeof ing.quantity === 'number' ? ing.quantity : null,
        unit: ing.unit ? String(ing.unit).trim() : null,
        matchedInventoryItemId: ing.matchedInventoryItemId || null,
        suggestedDeductionQuantity: typeof ing.suggestedDeductionQuantity === 'number' ? ing.suggestedDeductionQuantity : null,
        deductionNeedsUserConfirmation: true
      });
    }
  }
  const nutr = m.nutrition || {};
  meal = {
    name: m.name ? String(m.name).trim() : 'Recommended Meal',
    mealType: m.mealType ? String(m.mealType).toLowerCase().trim() : 'lunch',
    description: m.description ? String(m.description).trim() : '',
    preparationTimeMinutes: typeof m.preparationTimeMinutes === 'number' ? m.preparationTimeMinutes : 25,
    reason: m.reason ? String(m.reason).trim() : 'Suits your fridge ingredients.',
    ingredients: ingredients,
    missingIngredients: Array.isArray(m.missingIngredients) ? m.missingIngredients.map(String) : [],
    calories: typeof m.calories === 'number' ? Math.round(m.calories) : 450,
    proteinG: typeof m.proteinG === 'number' ? Math.round(m.proteinG) : 20,
    carbsG: typeof m.carbsG === 'number' ? Math.round(m.carbsG) : 50,
    fatG: typeof m.fatG === 'number' ? Math.round(m.fatG) : 15,
    nutritionIsEstimate: true,
    nutrition: {
      calories: typeof nutr.calories === 'number' ? Math.round(nutr.calories) : 450,
      proteinG: typeof nutr.proteinG === 'number' ? Math.round(nutr.proteinG) : 20,
      carbsG: typeof nutr.carbsG === 'number' ? Math.round(nutr.carbsG) : 50,
      fatG: typeof nutr.fatG === 'number' ? Math.round(nutr.fatG) : 15,
      isEstimate: true,
      estimateNote: nutr.estimateNote || 'Nutritional values are approximate AI estimates.'
    }
  };
}

return [{
  json: {
    ok: true,
    httpStatus: 200,
    responseBody: {
      ok: true,
      requestId: originalRequestId,
      action: action,
      assistantMessage: assistantMessage,
      requiresConfirmation: requiresConfirmation,
      needsClarification: needsClarification,
      clarifyingQuestion: clarifyingQuestion,
      inventoryItems: inventoryItems,
      meal: meal,
      warnings: Array.isArray(parsed.warnings) ? parsed.warnings : [],
      timings: {
        geminiDurationMs: geminiDurationMs
      }
    }
  }
}];
